  ["Open with %s"] = "Öffnen mit %s",
  ["Commands: /fhp (open or close), /fhp zones (zones without a map), /fhp api (API probe), /fhp map (map probe), /fhp tame (taming probe), /fhp owner (owner probe), /fhp share (sharing status), /fhp search (greet other hunters), /fhp survey (survey status), /fhp area (progress in this zone), /fhp tour (show the tour again)"] = "Befehle: /fhp (öffnen oder schließen), /fhp zonen (Gebiete ohne Karte), /fhp api (API-Probe), /fhp karte (Karten-Probe), /fhp zaehmen (Zähm-Probe), /fhp besitzer (Besitzer-Probe), /fhp teilen (Stand beim Teilen), /fhp suchen (andere Jäger grüßen), /fhp erhebung (Stand der Erhebung), /fhp gebiet (Fortschritt in diesem Gebiet), /fhp tour (Tour noch einmal ansehen)",
